    i += 1;
    return {
      type: 'NUMBER',
      value: src.slice(start, i),
      start,
      end: i,
      line,
      numKind: 'imaginary',
      numValue: Number(numText),
    };
  }
  if (isFloat) {
    return {
      type: 'NUMBER',
      value: src.slice(start, i),
      start,
      end: i,
      line,
      numKind: 'float',
      numValue: Number(numText),
    };
  }
  // Plain integer.  Leading zeros ("012") are a SyntaxError in CPython; per
  // spec we deliberately accept them as decimal.
  let dec = numText;
  while (dec.length > 1 && dec[0] === '0') dec = dec.slice(1);
  return {
    type: 'NUMBER',
    value: src.slice(start, i),
    start,
    end: i,
    line,
    numKind: 'int',
    numValue: BigInt(dec),
  };
}

/* ------------------------------------------------------------------ *
 * The tokenizer
 * ------------------------------------------------------------------ */

export function tokenize(src) {
  const toks = [];
  const n = src.length;
  let i = 0;
  let line = 1;

  while (i < n) {
    const c = src[i];

    // --- whitespace / newlines (the source is one logical line) ---
    if (c === '\n') {
      line += 1;
      i += 1;
      continue;
    }
    if (c === ' ' || c === '\t' || c === '\r' || c === '\f' || c === '\v') {
      i += 1;
      continue;
    }

    // --- comments ---
    if (c === '#') {
      while (i < n && src[i] !== '\n') i += 1;
      continue;
    }

    // --- explicit line continuation ---
    if (c === '\\') {
      if (src[i + 1] === '\n') {
        i += 2;
        line += 1;
        continue;
      }
      if (src[i + 1] === '\r') {
        i += 2;
        if (src[i] === '\n') i += 1;
        line += 1;
        continue;
      }
      syntaxError(src, i, 'unexpected character after line continuation character');
    }

    // --- strings (with or without a prefix) ---
    if (isQuote(c)) {
      i = pushString(src, toks, i, i, { raw: false, isBytes: false, isFString: false }, line);
      continue;
    }
    if (isIdentStart(c)) {
      const pre = tryStringPrefix(src, i);
      if (pre) {
        i = pushString(src, toks, i, i + pre.len, pre, line);
        continue;
      }
      let j = i + 1;
      while (j < n && isIdentCont(src[j])) j += 1;
      toks.push({ type: 'NAME', value: src.slice(i, j), start: i, end: j, line });
      i = j;
      continue;
    }

    // --- numbers ---
    if (isDigit(c) || (c === '.' && isDigit(src[i + 1]))) {
      const t = scanNumber(src, i, line);
      toks.push(t);
      i = t.end;
      continue;
    }

    // --- operators / delimiters, longest match first ---
    let matched = null;
    for (const op of OPS3) {
      if (src.startsWith(op, i)) {
        matched = op;
        break;
      }
    }
    if (!matched) {
      for (const op of OPS2) {
        if (src.startsWith(op, i)) {
          matched = op;
          break;
        }
      }
    }
    if (!matched && OPS1.indexOf(c) >= 0) matched = c;
    if (matched) {
      toks.push({
        type: 'OP',
        value: matched,
        start: i,
        end: i + matched.length,
        line,
      });
      i += matched.length;
      continue;
    }

    syntaxError(src, i, 'invalid syntax');
  }

  toks.push({ type: 'EOF', value: '', start: n, end: n, line });
  return toks;
}

/** Tokenize one string literal starting at `tokStart` (quote at `qPos`). */
function pushString(src, toks, tokStart, qPos, flags, line) {
  const q = src[qPos];
  const triple = src[qPos + 1] === q && src[qPos + 2] === q;
  const bodyStart = qPos + (triple ? 3 : 1);
  const { bodyEnd, end } = scanStringEnd(src, q, triple, bodyStart, tokStart);
  const tok = {
    type: 'STRING',
    value: src.slice(tokStart, end),
    start: tokStart,
    end,
    line,
    isBytes: flags.isBytes,
    isFString: flags.isFString,
    strValue: null,
    fParts: null,
  };
  if (flags.isFString) {
    tok.fParts = scanFStringParts(src, bodyStart, bodyEnd, flags, tokStart);
    // Convenience: the concatenated literal text (only meaningful when the
    // f-string contains no replacement fields).
    let lit = '';
    for (const p of tok.fParts) if (p.kind === 'lit') lit += p.text;
    tok.strValue = lit;
  } else {
    tok.strValue = decodeBody(src, bodyStart, bodyEnd, flags, tokStart);
  }
  toks.push(tok);
  return end;
}

/**
 * parser.mjs — recursive-descent parser for the Python 3 expression grammar.
 *
 * Produces the AST node shapes the evaluator is written against.  Precedence,
 * from loosest to tightest, mirrors CPython's grammar:
 *
 *   lambda / conditional  ->  or  ->  and  ->  not  ->  comparison (chained)
 *   ->  |  ->  ^  ->  &  ->  << >>  ->  + -  ->  * / // % @
 *   ->  unary + - ~  ->  **  ->  trailers (call / subscript / attribute)
 *
 * `**` is right-associative and its RIGHT operand is a *factor*, so `2**-1`
 * parses and `-2**2` is `-(2**2)`.
 *
 * `eval()` accepts exactly one expression: anything left over after it (a
 * stray `;`, a second expression) is a SyntaxError.  An empty or
 * whitespace-only source reports `lineno 0` with an empty source line, just
 * like CPython.
 */

import {
  PyError,
  PyBytes,
  PyComplex,
  PY_NONE,
  PY_TRUE,
  PY_FALSE,
  PY_ELLIPSIS,
} from '../pyvalues.mjs';
import { tokenize, syntaxError } from './tokenizer.mjs';

/** Comparison operators that arrive as OP tokens. */
const COMP_OPS = new Set(['<', '>', '<=', '>=', '==', '!=']);
/** Multiplicative operators. */
const TERM_OPS = new Set(['*', '/', '//', '%', '@']);

/**
 * Parse a complete Python expression.
 * @param {string} src
 * @returns {object} AST root
 */
export function parseExpression(src) {
  const toks = tokenize(src);
  let p = 0;

  /* ---------------- cursor helpers ---------------- */

  const peek = (k = 0) => toks[p + k < toks.length ? p + k : toks.length - 1];
  const next = () => toks[p < toks.length - 1 ? p++ : p];
  const atEof = () => peek().type === 'EOF';
  const isOp = (v, k = 0) => {
    const t = peek(k);
    return t.type === 'OP' && t.value === v;
  };
  const isKw = (v, k = 0) => {
    const t = peek(k);
    return t.type === 'NAME' && t.value === v;
  };
  const err = (tok, msg = 'invalid syntax') =>
    syntaxError(src, tok === undefined || tok === null ? src.length : tok.start, msg);
  const expectOp = (v, msg) => {
    if (!isOp(v)) err(peek(), msg === undefined ? 'invalid syntax' : msg);
    return next();
  };
  const expectKw = (v, msg) => {
    if (!isKw(v)) err(peek(), msg === undefined ? 'invalid syntax' : msg);
    return next();
  };
  const expectName = () => {
    if (peek().type !== 'NAME' || isReserved(peek().value)) err(peek());
    return next().value;
  };

  /* ---------------- entry ---------------- */

  if (atEof()) {
    // CPython reports line 0 with an empty text for an empty `eval` source.
    const e = new PyError('SyntaxError', 'invalid syntax');
    e.lineno = 0;
    e.text = '';
    e.offset = 0;
    throw e;
  }

  const root = parseTestListStar(null);
  if (!atEof()) err(peek());
  return root;

  /* ================================================================ *
   * Expression lists (bare tuples)
   * ================================================================ */

  /**
   * `(test|star_expr) (',' (test|star_expr))* [',']`
   * `closers` is the set of OP values that terminate the list (null = EOF).
   */
  function parseTestListStar(closers) {
    const first = parseStarOrTest();
    if (!isOp(',')) return first;
    const elts = [first];
    while (isOp(',')) {
      next();
      if (atListEnd(closers)) break;
      elts.push(parseStarOrTest());
    }
    return { type: 'Tuple', elts };
  }

  function atListEnd(closers) {
    if (atEof()) return true;
    if (closers === null) return false;
    const t = peek();
    return t.type === 'OP' && closers.indexOf(t.value) >= 0;
  }

  function parseStarOrTest() {
    if (isOp('*')) {
      next();
      return { type: 'Starred', value: parseOr() };
    }
    if (isOp('**')) {
      // Only legal in dict displays / calls; handled there.  Reaching here is
      // a syntax error.
      err(peek());
    }
    return parseTest();
  }

  /* ================================================================ *
   * Conditional / lambda
   * ================================================================ */

  function parseTest() {
    if (isKw('lambda')) return parseLambda();
    const body = parseOr();
    if (isKw('if')) {
      next();
      const test = parseOr();
      if (!isKw('else')) err(peek(), "expected 'else' after 'if' expression");
      next();
      const orelse = parseTest();
      return { type: 'IfExp', test, body, orelse };
    }
    return body;
  }

  /** `expression_nocond`: no bare conditional (used by comprehension `if`). */
  function parseTestNoCond() {
    if (isKw('lambda')) return parseLambda();
    return parseOr();
  }

  function parseLambda() {
    next(); // 'lambda'
    const args = { params: [], vararg: null, kwarg: null };
    while (!isOp(':')) {
      if (isOp('**')) {
        next();
        args.kwarg = expectName();
      } else if (isOp('*')) {
        next();
        // A bare `*` is only a keyword-only marker; nothing to record.
        if (peek().type === 'NAME' && !isReserved(peek().value)) args.vararg = next().value;
      } else if (isOp('/')) {
        next(); // positional-only marker
      } else if (peek().type === 'NAME' && !isReserved(peek().value)) {
        const name = next().value;
        let dflt = null;
        if (isOp('=')) {
          next();
          dflt = parseTest();
        }
        args.params.push({ name, default: dflt });
      } else {
        err(peek());
      }
      if (isOp(',')) next();
      else break;
    }
    expectOp(':');
    const body = parseTest();
    return { type: 'Lambda', args, body };
  }

  /* ================================================================ *
   * Boolean / comparison levels
   * ================================================================ */

  function parseOr() {
    let left = parseAnd();
    if (!isKw('or')) return left;
    const values = [left];
    while (isKw('or')) {
      next();
      values.push(parseAnd());
    }
    return { type: 'BoolOp', op: 'or', values };
  }

  function parseAnd() {
    let left = parseNot();
    if (!isKw('and')) return left;
    const values = [left];
    while (isKw('and')) {
      next();
      values.push(parseNot());
    }
    return { type: 'BoolOp', op: 'and', values };
  }

  function parseNot() {
    if (isKw('not')) {
      next();
      return { type: 'UnaryOp', op: 'not', operand: parseNot() };
    }
    return parseComparison();
  }

  function parseComparison() {
    const left = parseBitOr();
    const ops = [];
    const comparators = [];
    for (;;) {
      const t = peek();
      let op = null;
      if (t.type === 'OP' && COMP_OPS.has(t.value)) {
        op = t.value;
        next();
      } else if (t.type === 'NAME' && t.value === 'in') {
        op = 'in';
        next();
      } else if (t.type === 'NAME' && t.value === 'not' && isKw('in', 1)) {
        op = 'not in';
        next();
        next();
      } else if (t.type === 'NAME' && t.value === 'is') {
        next();
        if (isKw('not')) {
          next();
          op = 'is not';
        } else {
          op = 'is';
        }
      } else {
        break;
      }
      ops.push(op);
      comparators.push(parseBitOr());
    }
    if (ops.length === 0) return left;
    return { type: 'Compare', left, ops, comparators };
  }

  /* ================================================================ *
   * Binary operator levels
   * ================================================================ */

  function parseBitOr() {
    let left = parseBitXor();
    while (isOp('|')) {
      next();
      left = { type: 'BinOp', op: '|', left, right: parseBitXor() };
    }
    return left;
  }

  function parseBitXor() {
    let left = parseBitAnd();
    while (isOp('^')) {
      next();
      left = { type: 'BinOp', op: '^', left, right: parseBitAnd() };
    }
    return left;
  }

  function parseBitAnd() {
    let left = parseShift();
    while (isOp('&')) {
      next();
      left = { type: 'BinOp', op: '&', left, right: parseShift() };
    }
    return left;
  }

  function parseShift() {
    let left = parseArith();
    while (isOp('<<') || isOp('>>')) {
      const op = next().value;
      left = { type: 'BinOp', op, left, right: parseArith() };
    }
    return left;
  }

  function parseArith() {
    let left = parseTerm();
    while (isOp('+') || isOp('-')) {
      const op = next().value;
      left = { type: 'BinOp', op, left, right: parseTerm() };
    }
    return left;
  }

  function parseTerm() {
    let left = parseFactor();
    for (;;) {
      const t = peek();
      if (t.type !== 'OP' || !TERM_OPS.has(t.value)) break;
      next();
      left = { type: 'BinOp', op: t.value, left, right: parseFactor() };
    }
    return left;
  }

  /** unary `+ - ~` — binds looser than `**` on its right. */
  function parseFactor() {
    if (isOp('+') || isOp('-') || isOp('~')) {
      const op = next().value;
      return { type: 'UnaryOp', op, operand: parseFactor() };
    }
    return parsePower();
  }

  /** `**` is right-associative and takes a *factor* on the right. */
  function parsePower() {
    const base = parsePrimary();
    if (isOp('**')) {
      next();
      return { type: 'BinOp', op: '**', left: base, right: parseFactor() };
    }
    return base;
  }

  /* ================================================================ *
   * Trailers
   * ================================================================ */

  function parsePrimary() {
    let node = parseAtom();
    for (;;) {
      if (isOp('(')) {
        node = parseCall(node);
      } else if (isOp('[')) {
        next();
        if (isOp(']')) err(peek());
        const slice = parseSubscriptList();
        expectOp(']');
        node = { type: 'Subscript', value: node, slice };
      } else if (isOp('.')) {
        next();
        if (peek().type !== 'NAME') err(peek());
        node = { type: 'Attribute', value: node, attr: next().value };
      } else {
        return node;
      }
    }
  }

  function parseCall(func) {
    expectOp('(');
    const args = [];
    const keywords = [];
    let sawKeyword = false;
    while (!isOp(')')) {
      if (isOp('**')) {
        next();
        keywords.push({ arg: null, value: parseTest() });
        sawKeyword = true;
      } else if (isOp('*')) {
        next();
        args.push({ type: 'Starred', value: parseTest() });
      } else if (
        peek().type === 'NAME' &&
        !isReserved(peek().value) &&
        isOp('=', 1)
      ) {
        const name = next().value;
        next(); // '='
        keywords.push({ arg: name, value: parseTest() });
        sawKeyword = true;
      } else {
        const v = parseTest();
        if (isKw('for')) {
          // `f(x for x in y)` — a bare generator expression argument.
          const generators = parseComprehensions();
          args.push({ type: 'GeneratorExp', elt: v, generators });
        } else {
          if (sawKeyword) err(peek(), 'positional argument follows keyword argument');
          args.push(v);
        }
      }
      if (isOp(',')) next();
      else break;
    }
    expectOp(')');
    return { type: 'Call', func, args, keywords };
  }

  /** `x[a]`, `x[a:b:c]`, `x[a, b:c]` */
  function parseSubscriptList() {
    const first = parseSubscriptItem();
    if (!isOp(',')) return first;
    const elts = [first];
    while (isOp(',')) {
      next();
      if (isOp(']')) break;
      elts.push(parseSubscriptItem());
    }
    return { type: 'Tuple', elts };
  }

  function parseSubscriptItem() {
    let lower = null;
    if (!isOp(':')) {
      lower = parseStarOrTest();
      if (!isOp(':')) return lower;
    }
    expectOp(':');
    let upper = null;
    let step = null;
    if (!isOp(':') && !isOp(']') && !isOp(',')) upper = parseTest();
    if (isOp(':')) {
      next();
      if (!isOp(']') && !isOp(',')) step = parseTest();
    }
    return { type: 'Slice', lower, upper, step };
  }

  /* ================================================================ *
   * Comprehensions
   * ================================================================ */

  /** `('for' targetlist 'in' or_test ('if' nocond)*)+` */
  function parseComprehensions() {
    const generators = [];
    while (isKw('for') || (isKw('async') && isKw('for', 1))) {
      if (isKw('async')) next();
      next(); // 'for'
      const target = parseTargetList();
      expectKw('in');
      const iter = parseOr();
      const ifs = [];
      while (isKw('if')) {
        next();
        ifs.push(parseTestNoCond());
      }
      generators.push({ target, iter, ifs });
    }
    if (generators.length === 0) err(peek());
    return generators;
  }

  function parseTargetList() {
    const first = parseTarget();
    if (!isOp(',')) return first;
    const elts = [first];
    while (isOp(',')) {
      next();
      if (isKw('in')) break;
      elts.push(parseTarget());
    }
    return { type: 'Tuple', elts };
  }

  function parseTarget() {
    if (isOp('*')) {
      next();
      return { type: 'Starred', value: parseTarget() };
    }
    if (isOp('(') || isOp('[')) {
      const open = next().value;
      const close = open === '(' ? ')' : ']';
      const elts = [];
      while (!isOp(close)) {
        elts.push(parseTarget());
        if (isOp(',')) next();
        else break;
      }
      expectOp(close);
      if (open === '(' && elts.length === 1) return elts[0];
      return { type: open === '(' ? 'Tuple' : 'List', elts };
    }
    if (peek().type !== 'NAME' || isReserved(peek().value)) err(peek());
    return { type: 'Name', id: next().value };
  }

  /* ================================================================ *
   * Atoms
   * ================================================================ */

  function parseAtom() {
    const t = peek();

    if (t.type === 'NUMBER') {
      next();
      if (t.numKind === 'imaginary') {
        return { type: 'Constant', value: new PyComplex(0, t.numValue) };
      }
      return { type: 'Constant', value: t.numValue };
    }

    if (t.type === 'STRING') return parseStringGroup();

    if (t.type === 'NAME') {
      if (t.value === 'True') {
        next();
        return { type: 'Constant', value: PY_TRUE };
      }
      if (t.value === 'False') {
        next();
        return { type: 'Constant', value: PY_FALSE };
      }
      if (t.value === 'None') {
        next();
        return { type: 'Constant', value: PY_NONE };
      }
      if (t.value === 'Ellipsis') {
        next();
        return { type: 'Constant', value: PY_ELLIPSIS };
      }
      if (t.value === 'lambda') return parseLambda();
      if (isReserved(t.value)) err(t);
      next();
      return { type: 'Name', id: t.value };
    }

    if (t.type === 'OP') {
      if (t.value === '...') {
        next();
        return { type: 'Constant', value: PY_ELLIPSIS };
      }
      if (t.value === '(') return parseParenAtom();
      if (t.value === '[') return parseListAtom();
      if (t.value === '{') return parseBraceAtom();
    }

    err(t);
  }

  /** `()`, `(expr)`, `(a, b)`, `(x for x in y)` */
  function parseParenAtom() {
    const open = next(); // '('
    if (isOp(')')) {
      next();
      return { type: 'Tuple', elts: [] };
    }
    const first = parseStarOrTest();
    if (isKw('for')) {
      const generators = parseComprehensions();
      closeBracket(')', open);
      return { type: 'GeneratorExp', elt: first, generators };
    }
    if (isOp(',')) {
      const elts = [first];
      while (isOp(',')) {
        next();
        if (isOp(')')) break;
        elts.push(parseStarOrTest());
      }
      closeBracket(')', open);
      return { type: 'Tuple', elts };
    }
    closeBracket(')', open);
    // Plain grouping: no node of its own, exactly like CPython's AST.
    return first;
  }

  /** `[]`, `[a, b]`, `[x for x in y]` */
  function parseListAtom() {
    const open = next(); // '['
    if (isOp(']')) {
      next();
      return { type: 'List', elts: [] };
    }
    const first = parseStarOrTest();
    if (isKw('for')) {
      const generators = parseComprehensions();
      closeBracket(']', open);
      return { type: 'ListComp', elt: first, generators };
    }
    const elts = [first];
    while (isOp(',')) {
      next();
      if (isOp(']')) break;
      elts.push(parseStarOrTest());
    }
    closeBracket(']', open);
    return { type: 'List', elts };
  }

  /** `{}`, `{a: b}`, `{a, b}`, plus dict/set comprehensions and `**` unpacking */
  function parseBraceAtom() {
    const open = next(); // '{'
    if (isOp('}')) {
      next();
      return { type: 'Dict', keys: [], values: [] };
    }

    // `{**m}` is unambiguously a dict.
    if (isOp('**')) return parseDictRest(open, [], []);

    const first = parseStarOrTest();

    if (isOp(':')) {
      next();
      const val = parseTest();
      if (isKw('for')) {
        const generators = parseComprehensions();
        closeBracket('}', open);
        return { type: 'DictComp', key: first, value: val, generators };
      }
      const keys = [first];
      const values = [val];
      if (isOp(',')) {
        next();
        return parseDictRest(open, keys, values);
      }
      closeBracket('}', open);
      return { type: 'Dict', keys, values };
    }

    if (isKw('for')) {
      const generators = parseComprehensions();
      closeBracket('}', open);
      return { type: 'SetComp', elt: first, generators };
    }

    const elts = [first];
    while (isOp(',')) {
      next();
      if (isOp('}')) break;
      elts.push(parseStarOrTest());
    }
    closeBracket('}', open);
    return { type: 'Set', elts };
  }

  /** Continue a dict display; `keys`/`values` already hold the parsed pairs. */
  function parseDictRest(open, keys, values) {
    while (!isOp('}')) {
      if (isOp('**')) {
        next();
        keys.push(null);
        values.push(parseOr());
      } else {
        const k = parseTest();
        expectOp(':');
        keys.push(k);
        values.push(parseTest());
      }
      if (isOp(',')) next();
      else break;
    }
    closeBracket('}', open);
    return { type: 'Dict', keys, values };
  }

  /** Close a bracket, reporting CPython's "never closed" message at the open. */
  function closeBracket(close, openTok) {
    if (!isOp(close)) {
      if (atEof()) err(openTok, "'" + openTok.value + "' was never closed");
      err(peek());
    }
    next();
  }

  /* ================================================================ *
   * String literals (implicit concatenation + f-strings)
   * ================================================================ */

  function parseStringGroup() {
    const first = peek();
    const parts = [];
    while (peek().type === 'STRING') parts.push(next());

    let anyBytes = false;
    let allBytes = true;
